// Gemini a veces devuelve importes como texto ("1.234,56"): los pasamos a número
const aNumero = v => {
  if (typeof v === 'number') return v;
  if (v === null || v === undefined) return undefined;
  let t = String(v).replace(/[^\d,.\-]/g, '');
  if (!t) return undefined;
  const coma = t.lastIndexOf(','), punto = t.lastIndexOf('.');
  if (coma > -1 && punto > -1) {
    // el último separador es el decimal
    t = coma > punto ? t.replace(/\./g, '').replace(',', '.') : t.replace(/,/g, '');
  } else if (coma > -1) {
    t = t.split(',').length > 2 ? t.replace(/,/g, '') : t.replace(',', '.');
  } else if (t.split('.').length > 2) {
    t = t.replace(/\./g, '');
  }
  const n = Number(t);
  return Number.isFinite(n) ? n : undefined;
};
const camposCabecera = ['total_base', 'total_iva_porcentaje', 'total_iva_importe', 'total_irpf_porcentaje', 'total_irpf_importe', 'total_factura'];
const camposLinea = ['cantidad', 'precio_unitario', 'descuento_porcentaje', 'importe_linea_sin_iva', 'iva_porcentaje', 'iva_importe', 'importe_linea_total'];

try {
  let raw = $input.first().json.candidates[0].content.parts[0].text;

  raw = raw.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();

  const parsed = JSON.parse(raw);
  // Un total que no se puede leer como número queda vacío para que lo recoja "Tiene Total"
  if (parsed.cabecera) {
    for (const campo of camposCabecera) {
      if (campo in parsed.cabecera) parsed.cabecera[campo] = aNumero(parsed.cabecera[campo]) ?? (campo === 'total_factura' ? null : parsed.cabecera[campo]);
    }
  }
  // Empresas del grupo (nosotros): la factura la emite un tercero (emisor) a nombre de una de ellas (cliente)
  const CIF_GRUPO = { MARSAF: 'B54874334', DIANIA: 'B54707906' };
  const normCif = v => String(v ?? '').toUpperCase().replace(/[^A-Z0-9]/g, '').replace(/^ES/, '');
  const normTxt = v => String(v ?? '').normalize('NFD').replace(/[̀-ͯ]/g, '').toUpperCase().trim();
  // CIF del grupo al que corresponde la parte (por su CIF o por su nombre); '' si no es del grupo
  const cifGrupo = (nombre, cif) => {
    const c = normCif(cif);
    if (Object.values(CIF_GRUPO).includes(c)) return c;
    const n = normTxt(nombre);
    return n.includes('MARSAF') ? CIF_GRUPO.MARSAF : n.includes('DIANIA') ? CIF_GRUPO.DIANIA : '';
  };
  let avisoGrupo = '';
  let incoherenciaGrupo = '';
  if (parsed.cabecera) {
    const cab = parsed.cabecera;
    const emisorEsGrupo = !!cifGrupo(cab.emisor_nombre, cab.emisor_cif);
    const clienteEsGrupo = !!cifGrupo(cab.cliente_nombre, cab.cliente_cif);
    const mismaEmpresa = !emisorEsGrupo && ((normCif(cab.emisor_cif) && normCif(cab.emisor_cif) === normCif(cab.cliente_cif)) || (normTxt(cab.emisor_nombre) && normTxt(cab.emisor_nombre) === normTxt(cab.cliente_nombre)));
    const partes = 'emisor "' + (cab.emisor_nombre ?? '') + '", cliente "' + (cab.cliente_nombre ?? '') + '"';
    if (mismaEmpresa) {
      incoherenciaGrupo = 'El emisor y el cliente son la misma empresa y no son del grupo (Diania/Marsaf): revisar el documento (' + partes + ')';
    } else if (emisorEsGrupo && !clienteEsGrupo) {
      // Gemini los ha devuelto al revés: se intercambian
      [cab.emisor_nombre, cab.cliente_nombre] = [cab.cliente_nombre, cab.emisor_nombre];
      [cab.emisor_cif, cab.cliente_cif] = [cab.cliente_cif, cab.emisor_cif];
      avisoGrupo = 'Emisor y cliente venían invertidos: corregido automáticamente (' + partes + ' antes de corregir)';
    } else if (emisorEsGrupo && clienteEsGrupo) {
      incoherenciaGrupo = 'El emisor y el cliente son empresas del grupo (Diania/Marsaf): revisar el documento (' + partes + ')';
    } else if (!emisorEsGrupo && !clienteEsGrupo) {
      incoherenciaGrupo = 'Ni el emisor ni el cliente son Diania Logistics o Marsaf: revisar el documento (' + partes + ')';
    }
    // El cliente es nuestra empresa: se guarda siempre su CIF del grupo (Gemini no lo devuelve o puede traerlo con otro formato)
    const cifNuestro = cifGrupo(cab.cliente_nombre, cab.cliente_cif);
    if (cifNuestro && !incoherenciaGrupo) cab.cliente_cif = cifNuestro;
  }
  const numeroFactura = parsed.cabecera?.numero_factura?.toString().replace(/^0+/, '');

  // Red de seguridad por si el agente no devuelve el array de líneas
  const lineasArray = (parsed.lineas || []).map(linea => {
    const l = { ...linea };
    for (const campo of camposLinea) {
      if (campo in l) l[campo] = aNumero(l[campo]) ?? l[campo];
    }
    return l;
  });

  // Líneas sin IVA (la factura lo aplica de forma global al final): se reparte el porcentaje de la cabecera
  const r2 = n => Math.round((n + Number.EPSILON) * 100) / 100;
  const pctCab = aNumero(parsed.cabecera?.total_iva_porcentaje);
  let avisoImportes = '';
  if (lineasArray.length && pctCab > 0 && lineasArray.every(l => !(Number(l.iva_porcentaje) > 0) && !(Number(l.iva_importe) > 0))) {
    for (const l of lineasArray) if (Number.isFinite(Number(l.importe_linea_sin_iva))) l.iva_porcentaje = pctCab;
    avisoImportes = 'Las líneas venían sin IVA: se ha aplicado el ' + pctCab + '% de la factura a cada línea';
  }
  // Línea con porcentaje de IVA pero sin importe de IVA o con el total sin IVA: se recalcula
  for (const l of lineasArray) {
    const base = Number(l.importe_linea_sin_iva), pct = Number(l.iva_porcentaje);
    if (l.importe_linea_sin_iva !== null && Number.isFinite(base) && pct > 0 && !(Number(l.iva_importe) > 0)) {
      l.iva_importe = r2(base * pct / 100);
      l.importe_linea_total = r2(base + l.iva_importe);
    }
  }
  // La suma de las líneas tiene que dar el total de la factura (más la retención, si hay)
  const totalCab = parsed.cabecera?.total_factura;
  if (lineasArray.length && typeof totalCab === 'number' && Number.isFinite(totalCab)) {
    const suma = r2(lineasArray.reduce((a, l) => a + (Number(l.importe_linea_total) || 0), 0));
    const esperado = r2(totalCab + (Number(parsed.cabecera.total_irpf_importe) || 0));
    if (Math.abs(suma - esperado) > Math.max(0.05, 0.005 * lineasArray.length) + 0.005) {
      avisoImportes += (avisoImportes ? ' | ' : '') + 'Importes que no cuadran: las líneas suman ' + suma.toFixed(2) + ' y el total de la factura es ' + esperado.toFixed(2) + ' (revisar las líneas antes de aprobar)';
    }
  }

  return [{
    json: {
      cabecera: {
        ...parsed.cabecera,
        numero_factura: numeroFactura
      },
      lineas: lineasArray,
      total_lineas: lineasArray.length,
      aviso_grupo: avisoGrupo,
      incoherencia_grupo: incoherenciaGrupo,
      aviso_importes: avisoImportes,
      pdf_base64: $('Buscamos en Proceso').first().json.pdf_base64,
      id_proceso: $('Buscamos en Proceso').first().json.id_proceso.trim(),
      email_origen: $('Buscamos en Proceso').first().json.email_origen,
      nombre_remitente: $('Buscamos en Proceso').first().json.nombre_remitente,
      nombre_archivo: $('Buscamos en Proceso').first().json.nombre_archivo,
      fecha_recepcion: $('Buscamos en Proceso').first().json.fecha_recepcion,
      hora_recepcion: $('Buscamos en Proceso').first().json.hora_recepcion,
      asunto_email: $('Buscamos en Proceso').first().json.asunto_email
    }
  }];
} catch(e) {
  return [{
    json: {
      error: 'JSON malformado: ' + e.message,
      raw_length: $input.first().json.candidates?.[0]?.content?.parts?.[0]?.text?.length || 0,
      id_proceso: $('Buscamos en Proceso').first().json.id_proceso,
      nombre_archivo: $('Buscamos en Proceso').first().json.nombre_archivo,
      email_origen: $('Buscamos en Proceso').first().json.email_origen
    }
  }];
}

const idProceso = $('Inserta Cabecera').first().json.id_proceso;
const rowsToDelete = [];

for (const [index, item] of Object.entries(items)) {
  if (item.json.id_proceso_lineas === idProceso) {
