  return [{ json: { rowNumber: 0 } }];
}

// Ordenar filas de mayor a menor para borrar sin desfasar índices
rowsToDelete.sort((a, b) => b - a);

return rowsToDelete.map(row => ({ json: { rowNumber: row } }));

